import{_ as n,C as s,o as r,c as i,j as t,a,E as d,a2 as l}from"./chunks/framework.Di-jvWLj.js";const b=JSON.parse('{"title":"OpenClaw","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/openclaw.md","filePath":"deployment/openclaw.md","lastUpdated":1792495823000}'),p={name:"deployment/openclaw.md"},c={id:"openclaw",tabindex:"-1"};function h(u,e,m,w,g,f){const o=s("Badge");return r(),i("div",null,[t("h1",c,[e[0]||(e[0]=a("OpenClaw ",-1)),d(o,{type:"warning",text:"Planned"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#openclaw","aria-label":'Permalink to "OpenClaw <Badge type="warning" text="Planned" />"'},"​",-1))]),e[3]||(e[3]=l('<div class="warning custom-block"><p class="custom-block-title">Planned</p><p>The OpenClaw notifier is planned (<code>@chamberu/notify-openclaw</code>). The MCP endpoint ships in <a href="/guide/http#mcp"><code>@chamberu/http</code></a>.</p></div><p>OpenClaw is a personal assistant gateway that connects chat channels to agents. chamberu&#39;s integration contract is <strong>&quot;MCP in, hooks out&quot;</strong>.</p><h2 id="mcp-in" tabindex="-1">MCP in <a class="header-anchor" href="#mcp-in" aria-label="Permalink to &quot;MCP in&quot;">​</a></h2><p>Each chamberu app serves an MCP endpoint at <code>/mcp</code> (Streamable HTTP, from <a href="/guide/http#mcp"><code>@chamberu/http</code></a>). OpenClaw lists it among its MCP servers and gets:</p><ul><li>one <code>run_&lt;agent&gt;</code> tool per agent with an <code>http()</code> trigger, which starts a run and returns the run id (or, with <code>waitSeconds</code>, waits up to a minute and returns the output or the pending approval),</li><li><code>get_run</code> and <code>list_runs</code> for status,</li><li><code>resume_run</code> to answer an approval with its token and a decision.</li></ul><p>The endpoint uses the same bearer-token authentication as the REST API; give OpenClaw a principal with <code>agent:&lt;name&gt;:run</code> (and <code>agent:&lt;name&gt;:approve</code> where it may answer approvals), which also lets it read the runs it starts. This is how the owner says &quot;what&#39;s relevant in my mail today?&quot; in a chat and gets a run started.</p><h2 id="hooks-out" tabindex="-1">Hooks out <a class="header-anchor" href="#hooks-out" aria-label="Permalink to &quot;Hooks out&quot;">​</a></h2><p>Results, approval requests and &quot;stuck&quot; pings flow back through the OpenClaw notifier: <code>POST &lt;openclaw&gt;/hooks/agent</code> with OpenClaw&#39;s hooks token as bearer token, the notifier&#39;s <code>idempotencyKey</code> as <code>Idempotency-Key</code> header, and the delivery target (channel and recipient). OpenClaw lets one of its agents phrase the message before delivering it.</p><p>For approvals the message includes how to answer: a link into the planned UI&#39;s approvals inbox, and the <code>resume_run</code> MCP tool, so the owner can approve from the chat.</p><h2 id="what-works-today" tabindex="-1">What works today <a class="header-anchor" href="#what-works-today" aria-label="Permalink to &quot;What works today&quot;">​</a></h2><p>The MCP side is in place (<a href="/guide/http"><code>@chamberu/http</code></a>), and so is the core side: approval notifications go through any <a href="/guide/notifiers"><code>INotifier</code></a> with a stable idempotency key and are retried until delivered, and <a href="/guide/approvals"><code>engine.resume()</code></a> answers them. The OpenClaw notifier itself is still planned.</p><h2 id="in-the-cluster" tabindex="-1">In the cluster <a class="header-anchor" href="#in-the-cluster" aria-label="Permalink to &quot;In the cluster&quot;">​</a></h2><p>OpenClaw runs elsewhere in the cluster. It reaches each app at <code>http://&lt;service&gt;/mcp</code>, and the app reaches OpenClaw&#39;s hooks endpoint. Neither needs to be public.</p>',13))])}const C=n(p,[["render",h]]);export{b as __pageData,C as default};
